mapper.select:
SELECT fi.id, fi.definition_id, fi.business_id, fd.name, fd.code, fi.category, fi.current_node_key, fi.current_node_name, fi.status, fi.start_time, fi.end_time FROM flow_instance fi INNER JOIN flow_definition fd ON fd.id = fi.definition_id
fi.org_id = #{query.orgId}
AND fi.user_id= #{query.userId}
AND (fd.name LIKE CONCAT('%', #{query.keyword}, '%') OR fd.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND fi.category = #{query.category}
AND fi.status = #{query.status}
AND fi.start_time >= #{query.startTimeBegin}
AND fi.start_time <= #{query.startTimeEnd}
ORDER BY fi.start_time DESC, fi.id DESC
